from collections import deque

def predict_output_v3(grid):
    """Fill cells based on being within bounding box of features"""
    h, w = len(grid), len(grid[0])

    # Find all feature points
    features = []

    # 3x3 regions (use top-left corner)
    for r in range(h-2):
        for c in range(w-2):
            is_region = True
            for dr in range(3):
                for dc in range(3):
                    val = grid[r+dr][c+dc]
                    if val == 0:
                        is_region = False
                    elif val == 2 and (dr != 1 or dc != 1):
                        pass
                    elif val == 2 and dr == 1 and dc == 1:
                        pass
                    elif val == 3:
                        pass
                    else:
                        is_region = False
            if is_region:
                # Add all 9 cells of the 3x3 as features
                for dr in range(3):
                    for dc in range(3):
                        features.append((r+dr, c+dc))

    # Lines of 2s - use start points of significant segments
    for r in range(h):
        segment_len = 0
        for c in range(w):
            if grid[r][c] == 2:
                segment_len += 1
            else:
                if segment_len >= 3:
                    features.append((r, c-segment_len))  # Start point
                segment_len = 0
        if segment_len >= 3:
            features.append((r, w-segment_len))  # End point

    for c in range(w):
        segment_len = 0
        for r in range(h):
            if grid[r][c] == 2:
                segment_len += 1
            else:
                if segment_len >= 3:
                    features.append((r-segment_len, c))  # Start point
                segment_len = 0
        if segment_len >= 3:
            features.append((h-segment_len, c))  # End point

    # Compute min/max bounds
    if not features:
        return grid

    r_min = min(f[0] for f in features)
    r_max = max(f[0] for f in features)
    c_min = min(f[1] for f in features)
    c_max = max(f[1] for f in features)

    print(f"Bbox: rows {r_min}-{r_max}, cols {c_min}-{c_max}")
    print(f"Number of feature cells: {len(features)}")

    # Expand bbox inward by some margin
    result = [list(row)[:] for row in grid]

    # Fill everything inside bbox with 1, except existing non-zeros
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            if grid[r][c] == 0:
                result[r][c] = 1

    return result

