def predict_v7(grid):
    """Fill cells based on connections between features"""
    h, w = len(grid), len(grid[0])

    # Find all 3x3 regions
    features = []
    for r in range(h-2):
        for c in range(w-2):
            is_region = True
            for dr in range(3):
                for dc in range(3):
                    val = grid[r+dr][c+dc]
                    if val == 0:
                        is_region = False
                    elif val == 3:
                        pass
                    else:
                        is_region = False
            if is_region:
                features.append((r+1, c+1))  # center

    result = [list(row)[:] for row in grid]

    if len(features) <= 1:
        return result

    # For multiple features, find connections
    # Look for vertical lines of 2s that could connect them

    # Simple version: for each pair of features, check if there's a vertical 2-line nearby
    # If so, fill cells between them

    n = len(features)
    for i in range(n):
        for j in range(i+1, n):
            f1_r, f1_c = features[i]
            f2_r, f2_c = features[j]

            # Find nearest vertical line segment in each column near both features
            for c in range(w):
                # Check if there's a continuous vertical segment near this column
                seg_start = None
                seg_end = None
                for r in range(h):
                    if grid[r][c] == 2:
                        if seg_start is None:
                            seg_start = r
                        seg_end = r
                    else:
                        if seg_start is not None:
                            break

                if seg_start is not None:
                    # Check if this line spans near both features
                    if abs(c - f1_c) <= 2 and abs(c - f2_c) <= 2:
                        # Line connects the features
                        # Fill from top feature to bottom feature at this column (or nearby)
                        min_fill_r = min(f1_r, f2_r) - 1
                        max_fill_r = max(f1_r, f2_r) + 1

                        for fill_r in range(min(max_fill_r, h), max(min_fill_r, -1), -1):
                            if fill_r < h and fill_r >= 0 and result[fill_r][c] == 0:
                                result[fill_r][c] = 1

    return result

